    "id": "reading:stories/maniabandha",
    "title": "Maniabandha: Where Odisha’s Weaving Heritage Meets a New Generation of Travellers",
    "author": "Ahimanikya Satapathy",
    "kind": "Reading",
    "area": "Cuttack",
    "summary": "In this village in Cuttack district, the future of textile tourism depends on understanding the skill behind the sari—and keeping its makers at the centre.",
    "href": "/stories/maniabandha/",
